interactive.css:
.board, .grid {
  margin: 20px 20px 20px 0;
  float: left;
  position: absolute;
  display: grid;
}
.board div, .grid div {
  text-align: center;
  width: 50px;
  height: 50px;
  font-size: 32px;
}
.grid {
  grid-template-columns: repeat(6, 50px);
}
.board {
  left: 25px;
  top: 25px;
  grid-template-columns: repeat(5, 50px);
}
.grid div {
  border: 1px solid #aaa;
}
.grid div:nth-child(-n+6) {
  border-top: 0px;
}
.grid div:nth-child(6n+1) {
    border-left: 0px;
}
.grid div:nth-last-child(-n+6) {
  border-bottom: 0px;
}
.grid div:nth-child(6n) {
  border-right: 0px;
}
